WITH base AS (
  SELECT cdscode, "fundingtype" AS ft FROM schools WHERE charter = 1 AND statustype = 'Active' AND "fundingtype" IN ('Directly funded','Locally funded')
),
s AS (SELECT cds, numtsttakr, avgscrread, avgscrmath, avgscrwrite FROM satscores WHERE avgscrread IS NOT NULL AND avgscrmath IS NOT NULL AND avgscrwrite IS NOT NULL)
SELECT b.ft, COUNT(*) AS sat_schools, ROUND(AVG(s.avgscrread + s.avgscrmath + s.avgscrwrite)::numeric, 2) AS avg_sat
FROM base b JOIN s ON s.cds = b.cdscode GROUP BY b.ft;

SELECT s.*, sc."school", sc."district", sc."city", sc."mailcity", sc."mailzip"
FROM satscores s LEFT JOIN schools sc ON sc."cdscode" = s."cds"
WHERE s."cds" = '43696410000000';
